"""On-disk shard directories: a persisted, resumable window-sharded export.

A shard directory holds one file per shard -- ``shard-00000000.json``,
``shard-00000001.json``, ... -- where each file's bytes are exactly the
canonical JSON of the corresponding in-memory shard proof, plus a
self-authenticating ``manifest.json``: one compact JSON line terminated
by a single newline, recording in shard order every shard's file name,
index interval and the sha256 of its file bytes, sealed by an
authentication tag over the whole manifest.

Every file is committed with a temp-file write + fsync + atomic rename
and the manifest is re-committed as each shard lands, so a process
killed in any commit window leaves the directory at either the old or
the new committed state -- never a half-written shard. A later export
call on the same directory resumes from the committed manifest: shards
the manifest vouches for are authenticated in place and never rewritten,
only the missing ones are produced.
"""

from __future__ import annotations

import contextlib
import hashlib
import json
import os
from typing import Any

from . import record as rec
from . import storage as st

MANIFEST_NAME = "manifest.json"
SHARD_PREFIX = "shard-"
SHARD_SUFFIX = ".json"
MANIFEST_VERSION = 1
_CHUNK = 1 << 20
_HEX64 = frozenset("0123456789abcdef")


def shard_name(index: int) -> str:
    return f"{SHARD_PREFIX}{index:08d}{SHARD_SUFFIX}"


def shard_count(start: int, end: int, window: int) -> int:
    """Shards needed to tile ``[start, end)`` with pieces of ``window``."""
    return -(-(end - start) // window)


def shard_slot(start: int, end: int, window: int, index: int) -> tuple[int, int]:
    """The index interval shard ``index`` of the tiling must cover."""
    lo = start + index * window
    return lo, min(lo + window, end)


def shard_bytes(shard: dict) -> bytes:
    """The canonical on-disk bytes of one shard: compact JSON, nothing else."""
    return rec.canonical_json(shard).encode("utf-8")


def file_digest(path: str) -> str:
    """Streaming sha256 of a file; memory stays bounded for any file size."""
    h = hashlib.sha256()
    with open(path, "rb") as handle:
        while True:
            chunk = handle.read(_CHUNK)
            if not chunk:
                return h.hexdigest()
            h.update(chunk)


def write_shard(directory: str, name: str, raw: bytes) -> None:
    """Commit one shard file (temp file + fsync + atomic rename)."""
    st.atomic_write_bytes(directory, name, raw)


def save_manifest(directory: str, manifest: dict) -> None:
    """Sign and commit the manifest as one compact JSON line + newline."""
    st.atomic_write_text(directory, MANIFEST_NAME, manifest_text(manifest))


def manifest_text(manifest: dict) -> str:
    return rec.canonical_json(sign_manifest(manifest)) + "\n"


def sign_manifest(manifest: dict) -> dict:
    """A manifest copy carrying its authentication tag."""
    signed = _manifest_body(manifest)
    signed["tag"] = hashlib.sha256(
        rec.canonical_json(signed).encode("utf-8")
    ).hexdigest()
    return signed


def load_manifest(directory: str) -> dict:
    """Read and authenticate the shard directory's manifest.

    ``FileNotFoundError`` when the manifest is absent; ``ValueError``
    when it cannot be parsed, is structurally invalid, or its
    authentication tag does not match its content.
    """
    with open(os.path.join(directory, MANIFEST_NAME), "rb") as handle:
        raw = handle.read()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError("malformed shard manifest") from exc
    # The on-disk form is one compact JSON line plus a trailing newline.
    if text.endswith("\n"):
        text = text[:-1]
    try:
        manifest = json.loads(text)
    except ValueError as exc:
        raise ValueError("malformed shard manifest") from exc
    if not _valid_manifest(manifest):
        raise ValueError("malformed shard manifest")
    expected = hashlib.sha256(
        rec.canonical_json(_manifest_body(manifest)).encode("utf-8")
    ).hexdigest()
    if not st.constant_time_equal(manifest["tag"], expected):
        raise ValueError("tampered shard manifest")
    return manifest


def reap_temp_files(directory: str) -> None:
    """Drop staging temp files left behind by a killed commit."""
    for name in os.listdir(directory):
        if name.startswith(".") and name.endswith(".tmp"):
            with contextlib.suppress(OSError):
                os.remove(os.path.join(directory, name))


def open_shard(directory: Any, index: Any) -> dict:
    """Read one shard back out of a shard directory, offline.

    The shard is located through the self-authenticating manifest and
    its bytes are checked against the manifest's recorded digest before
    it is returned, so a shard rewritten behind the manifest's back is
    reported rather than handed out. Neither the log nor any other
    shard is opened. The returned shard is an ordinary offline proof,
    verifiable with :func:`audit_chain.proof.verify_proof`.

    A missing directory, manifest or shard file raises
    ``FileNotFoundError``; an unparseable manifest or shard, a shard
    that does not match the manifest, or an out-of-range index raises
    ``ValueError``; a non-integer index raises ``TypeError``.
    """
    if not isinstance(index, int) or isinstance(index, bool):
        raise TypeError("shard index must be an integer")
    try:
        directory = os.fspath(directory)
    except TypeError:
        raise TypeError("directory must be a path-like object") from None
    if isinstance(directory, bytes):
        directory = os.fsdecode(directory)
    if index < 0:
        raise ValueError("shard index is out of range")
    if not os.path.isdir(directory):
        raise FileNotFoundError(directory)
    manifest = load_manifest(directory)
    shards = manifest["shards"]
    if index >= len(shards):
        raise ValueError("shard index is out of range")
    entry = shards[index]
    path = os.path.join(directory, entry["name"])
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    with open(path, "rb") as handle:
        raw = handle.read()
    if hashlib.sha256(raw).hexdigest() != entry["sha256"]:
        raise ValueError("shard file does not match the manifest")
    try:
        shard = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError) as exc:
        raise ValueError("malformed shard file") from exc
    if not isinstance(shard, dict):
        raise ValueError("malformed shard file")
    return shard


def _manifest_body(manifest: dict) -> dict:
    return {
        "version": manifest["version"],
        "tenant": manifest["tenant"],
        "start": manifest["start"],
        "end": manifest["end"],
        "window": manifest["window"],
        "shards": manifest["shards"],
    }


def _valid_manifest(manifest: Any) -> bool:
    if not isinstance(manifest, dict):
        return False
    if manifest.get("version") != MANIFEST_VERSION:
        return False
    if not isinstance(manifest.get("tenant"), str):
        return False
    start, end, window = (
        manifest.get("start"),
        manifest.get("end"),
        manifest.get("window"),
    )
    if not (_nonneg_int(start) and _nonneg_int(end)):
        return False
    if not _nonneg_int(window) or window == 0:
        return False
    if not start < end:
        return False
    shards = manifest.get("shards")
    if not isinstance(shards, list):
        return False
    # The entries are a prefix of the interval's tiling: a shorter list
    # is a committed checkpoint of an interrupted export, a longer one
    # can never have been written by an exporter of this interval.
    if len(shards) > shard_count(start, end, window):
        return False
    for index, entry in enumerate(shards):
        if not isinstance(entry, dict):
            return False
        lo, hi = shard_slot(start, end, window, index)
        if entry.get("name") != shard_name(index):
            return False
        if entry.get("start") != lo or entry.get("end") != hi:
            return False
        sha = entry.get("sha256")
        if (
            not isinstance(sha, str)
            or len(sha) != 64
            or any(char not in _HEX64 for char in sha)
        ):
            return False
    return isinstance(manifest.get("tag"), str)


def _nonneg_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0

"""Shared helpers for the audit-chain test suite."""

from __future__ import annotations

import json
import os
import sys
import tempfile
import unittest

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if REPO_ROOT not in sys.path:
    sys.path.insert(0, REPO_ROOT)


class AuditTestCase(unittest.TestCase):
    def setUp(self) -> None:
        self._tmp = tempfile.mkdtemp(prefix="audit-chain-test-")
        self.path = os.path.join(self._tmp, "log")
        self.chain = __import__("audit_chain").Chain(self.path)

    def tearDown(self) -> None:
        import shutil

        shutil.rmtree(self._tmp, ignore_errors=True)

    # -- low level helpers -------------------------------------------------

    def append_many(self, tenant: str, count: int, start: int = 0) -> None:
        for index in range(start, start + count):
            self.chain.append(tenant, {"i": index})

    def raw_bytes(self, name: str = "") -> bytes:
        target = os.path.join(self.path, name) if name else self.path
        with open(target, "rb") as handle:
            return handle.read()

    def write_raw(self, data: bytes, name: str = "") -> None:
        target = os.path.join(self.path, name) if name else self.path
        with open(target, "wb") as handle:
            handle.write(data)

    def segment_files(self) -> list[str]:
        return sorted(
            name
            for name in os.listdir(self.path)
            if name.startswith("seg-") and name.endswith(".jsonl")
        )

    def good_prefix(self, data: bytes | None = None) -> list[dict]:
        """Decode every complete newline-terminated line of raw bytes."""
        if data is None:
            data = self.raw_bytes()
        text = data.decode("utf-8")
        if not text:
            return []
        return [json.loads(line) for line in text.split("\n")[:-1]]

    def replace_in_file(self, old: bytes, new: bytes, name: str = "") -> None:
        data = self.raw_bytes(name)
        self.assertIn(old, data)
        self.assertEqual(len(old), len(new))
        self.write_raw(data.replace(old, new, 1), name)

"""Range export cost: work scales with the interval, not history length."""

from __future__ import annotations

import builtins
import hashlib
import os

from audit_chain import combine_proofs, verify_proof
from tests._helpers import AuditTestCase


class _ReadMeter:
    """Records total bytes read and every distinct file opened in binary."""

    def __init__(self) -> None:
        self.bytes = 0
        self.paths: set[str] = set()
        self._real_open = builtins.open

    def install(self) -> None:
        meter = self

        class CountingFile:
            def __init__(self_inner, raw) -> None:
                self_inner._f = raw

            def read(self_inner, *args):
                data = self_inner._f.read(*args)
                meter.bytes += len(data)
                return data

            def __enter__(self_inner):
                self_inner._f.__enter__()
                return self_inner

            def __exit__(self_inner, *exc):
                return self_inner._f.__exit__(*exc)

            def __getattr__(self_inner, name):
                return getattr(self_inner._f, name)

        def counting_open(path, *args, **kwargs):
            mode = args[0] if args else kwargs.get("mode", "r")
            handle = meter._real_open(path, *args, **kwargs)
            if "b" in mode:
                meter.paths.add(os.path.abspath(os.fspath(path)))
                return CountingFile(handle)
            return handle

        builtins.open = counting_open

    def remove(self) -> None:
        builtins.open = self._real_open


class _HashMeter:
    """Counts bytes fed to sha256 (same shape as test_cache.py)."""

    def __init__(self) -> None:
        self.bytes = 0
        self._real = hashlib.sha256

    def install(self) -> None:
        real = self._real
        meter = self

        def counting_sha256(data: bytes = b""):
            digest = real(data)
            meter.bytes += len(data)

            class _H:
                def update(self_inner, chunk: bytes) -> None:
                    meter.bytes += len(chunk)
                    digest.update(chunk)

                def hexdigest(self_inner) -> str:
                    return digest.hexdigest()

                def copy(self_inner):
                    return self_inner

            return _H()

        hashlib.sha256 = counting_sha256

    def remove(self) -> None:
        hashlib.sha256 = self._real


class ExportCostTest(AuditTestCase):
    HISTORY = 20_000
    ROTATE_EVERY = 5_000

    def _build(self, lo: int, hi: int) -> None:
        for i in range(lo, hi):
            self.chain.append("t", {"i": i, "pad": "x" * 24})
            if (i + 1) % self.ROTATE_EVERY == 0 and i + 1 < hi:
                self.chain.rotate()

    def _total_bytes(self) -> int:
        return sum(
            os.path.getsize(os.path.join(self.path, name))
            for name in os.listdir(self.path)
            if name.endswith(".jsonl")
        )

    def test_small_interval_does_not_hash_the_history(self) -> None:
        self._build(0, self.HISTORY)
        self.assertTrue(self.chain.verify("t")["ok"])  # warm the cache
        total = self._total_bytes()

        meter = _HashMeter()
        meter.install()
        try:
            proof = self.chain.export_range("t", 100, 200)
            hashed = meter.bytes
        finally:
            meter.remove()

        self.assertTrue(verify_proof(proof, start=100, end=200)["ok"])
        # Only the ~100 interval record digests, never a sealed window.
        self.assertLess(hashed, total // 100)

    def test_export_opens_only_covering_segments(self) -> None:
        self._build(0, self.HISTORY)
        self.assertTrue(self.chain.verify("t")["ok"])

        seg_files = {
            os.path.abspath(os.path.join(self.path, name))
            for name in self.segment_files()
        }
        # Interval [100, 200) lives wholly in the first segment.
        meter = _ReadMeter()
        meter.install()
        try:
            proof = self.chain.export_range("t", 100, 200)
        finally:
            meter.remove()

        self.assertTrue(verify_proof(proof, start=100, end=200)["ok"])
        opened_segments = meter.paths & seg_files
        self.assertEqual(len(opened_segments), 1)
        # The other (non-covering) segment files are never opened.
        self.assertLessEqual(
            meter.bytes, os.path.getsize(next(iter(opened_segments))) + 100_000
        )

    def test_cost_is_independent_of_history_length(self) -> None:
        self._build(0, self.HISTORY)
        self.assertTrue(self.chain.verify("t")["ok"])
        covering = os.path.join(self.path, self.segment_files()[0])
        covering_size = os.path.getsize(covering)
        first = _ReadMeter()
        first.install()
        try:
            self.chain.export_range("t", 100, 200)
            bytes_at_20k = first.bytes
        finally:
            first.remove()

        # Grow the history by another full set of segments; the same early
        # interval must read neither more of its covering segment nor any of
        # the newly added history.
        self._build(self.HISTORY, 2 * self.HISTORY)
        second = _ReadMeter()
        second.install()
        try:
            proof = self.chain.export_range("t", 100, 200)
            bytes_at_40k = second.bytes
        finally:
            second.remove()

        self.assertTrue(verify_proof(proof, start=100, end=200)["ok"])
        total = self._total_bytes()
        # Bounded by the single covering segment (plus small sidecars), far
        # below the whole history, and unchanged as history doubles.
        self.assertLess(bytes_at_40k, covering_size + 100_000)
        self.assertLess(bytes_at_40k, total // 8)
        self.assertLess(abs(bytes_at_40k - bytes_at_20k), 100_000)

    def test_active_tail_interval_hashes_only_interval_bytes(self) -> None:
        self._build(0, self.HISTORY)
        # Records beyond the last rotation sit in the un-sealed active unit,
        # interleaved with many co-tenant records.
        for i in range(self.HISTORY, self.HISTORY + 200):
            self.chain.append("t", {"i": i})
            for _ in range(5):
                self.chain.append("u", {"pad": "Z" * 40})
        self.assertTrue(self.chain.verify("t")["ok"])

        active = os.path.join(self.path, self.segment_files()[-1])
        active_size = os.path.getsize(active)

        meter = _HashMeter()
        meter.install()
        try:
            proof = self.chain.export_range(
                "t", self.HISTORY + 10, self.HISTORY + 110
            )
            hashed = meter.bytes
        finally:
            meter.remove()

        self.assertTrue(
            verify_proof(
                proof, start=self.HISTORY + 10, end=self.HISTORY + 110
            )["ok"]
        )
        # 100 small interval records, not the active unit nor the 1000 u rows.
        self.assertLess(hashed, active_size // 5)

    def test_combine_is_offline_and_hashes_no_history(self) -> None:
        self._build(0, self.HISTORY)
        self.assertTrue(self.chain.verify("t")["ok"])
        left = self.chain.export_range("t", 100, 150)
        right = self.chain.export_range("t", 150, 200)

        meter = _ReadMeter()
        meter.install()
        try:
            combined = combine_proofs(left, right)
            read_bytes = meter.bytes
        finally:
            meter.remove()

        # Splicing is purely in-memory: the log is never opened.
        self.assertEqual(read_bytes, 0)
        self.assertTrue(verify_proof(combined, start=100, end=200)["ok"])

