    return {
        "version": manifest["version"],
        "tenant": manifest["tenant"],
        "start": manifest["start"],
        "end": manifest["end"],
        "window": manifest["window"],
        "shards": manifest["shards"],
    }


def _valid_manifest(manifest: Any) -> bool:
