def check_entries(
    start: int, window: int, entries: Any, *, declared_end: int
) -> bool:
    """Validate the committed entries as one contiguous window tiling.

    The entries must begin at ``start``, each begin exactly where the
    previous one ended, span between one and ``window`` records, cover a
    full window on every entry but the last, and end at the declared
    prefix end without overshooting it. File names are the fixed
    ``shard-NNNNNNNN.json`` sequence and every digest is 64 hex chars.
    """
    if not isinstance(entries, list):
        return False
    cursor = start
    for index, entry in enumerate(entries):
        if not isinstance(entry, dict):
            return False
        lo, hi = entry.get("start"), entry.get("end")
        if not (_nonneg_int(lo) and _nonneg_int(hi)):
            return False
        if lo != cursor or hi <= lo or hi - lo > window:
            return False
        is_last = index == len(entries) - 1
        if not is_last and hi - lo != window:
            return False
        if entry.get("name") != shard_name(index):
            return False
        sha = entry.get("sha256")
        if not (
            isinstance(sha, str)
            and len(sha) == 64
            and all(char in _HEX64 for char in sha)
        ):
            return False
        cursor = hi
    return cursor <= declared_end

